package de.tum.cit.aet.artemis.atlas.dto;

import org.jspecify.annotations.Nullable;

import com.fasterxml.jackson.annotation.JsonInclude;

import de.tum.cit.aet.artemis.atlas.domain.competency.CompetencyLectureUnitLink;
import io.swagger.v3.oas.annotations.media.Schema;

/**
 * A lecture unit linked to a course competency.
 *
 * @param weight        how much the lecture unit contributes to mastery
 * @param generatedByAi whether the link was generated by AI
 * @param lectureUnit   the linked lecture unit, when available
 */
@JsonInclude(JsonInclude.Include.NON_EMPTY)
public record CompetencyLectureUnitLinkResponseDTO(@Schema(requiredMode = Schema.RequiredMode.REQUIRED) double weight,
        @Schema(requiredMode = Schema.RequiredMode.REQUIRED) boolean generatedByAi, @Nullable LectureUnitForCompetencyDTO lectureUnit) {

    @Nullable
    public static CompetencyLectureUnitLinkResponseDTO of(@Nullable CompetencyLectureUnitLink link) {
        if (link == null) {
            return null;
        }
        return new CompetencyLectureUnitLinkResponseDTO(link.getWeight(), link.isGeneratedByAi(), LectureUnitForCompetencyDTO.of(link.getLectureUnit()));
    }
}
